    {query.isLoading ? <div className="space-y-2">{[...Array(5)].map((_, i) => <Skeleton key={i} className="h-14" />)}</div> : query.isError ? <ErrorState error={query.error} onRetry={() => query.refetch()} /> : all.length === 0 ? <EmptyState icon={CreditCard} title="No invoices" description={isClient ? 'Invoices sent to you will appear here.' : 'Create an invoice to start tracking payments.'} action={isManagement && <Button onClick={() => setOpen(true)}><Plus />New invoice</Button>} /> : <Card><Table><TableHeader><TableRow><TableHead>Invoice</TableHead><TableHead>Client</TableHead><TableHead>Project</TableHead><TableHead>Status</TableHead><TableHead>Due</TableHead><TableHead className="text-right">Total</TableHead></TableRow></TableHeader><TableBody>{all.map((i) => <TableRow key={i.id}><TableCell><Link href={`/billing/${i.id}`} className="font-medium hover:text-primary">{i.number}</Link></TableCell><TableCell className="text-sm">{i.client.name}</TableCell><TableCell className="text-sm text-muted-foreground">{i.project?.name ?? '—'}</TableCell><TableCell><StatusBadge status={i.status} /></TableCell><TableCell className={i.status === 'OVERDUE' ? 'text-destructive text-sm' : 'text-sm'}>{formatDate(i.dueDate)}</TableCell><TableCell className="text-right font-medium">{formatMoney(i.total, i.currency)}</TableCell></TableRow>)}</TableBody></Table><div className="px-3 pb-3"><DataPagination page={query.data!.meta.page} totalPages={query.data!.meta.totalPages} total={query.data!.meta.total} onChange={setPage} /></div></Card>}
    <Dialog open={open} onOpenChange={setOpen}><DialogContent className="max-w-2xl"><DialogHeader><DialogTitle>New invoice</DialogTitle></DialogHeader><form onSubmit={form.handleSubmit((d) => create.mutate(d))} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><FormField label="Client" required error={form.formState.errors.clientId?.message}><Select value={form.watch('clientId')} onValueChange={(v) => form.setValue('clientId', v)}><SelectTrigger><SelectValue placeholder="Select client" /></SelectTrigger><SelectContent>{clients.data?.data.map((c) => <SelectItem key={c.id} value={c.id}>{c.name}</SelectItem>)}</SelectContent></Select></FormField><FormField label="Due date" required error={form.formState.errors.dueDate?.message}><Input type="date" {...form.register('dueDate')} /></FormField></div><div className="grid gap-4 sm:grid-cols-2"><FormField label="Currency"><Select value={form.watch('currency')} onValueChange={(v) => form.setValue('currency', v)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{['USD', 'EUR', 'GBP', 'TND'].map((c) => <SelectItem key={c} value={c}>{c}</SelectItem>)}</SelectContent></Select></FormField><FormField label="Tax rate (%)" error={form.formState.errors.taxRate?.message}><Input type="number" min={0} max={100} step="0.01" {...form.register('taxRate')} /></FormField></div>
      <div className="space-y-2"><p className="text-sm font-medium">Line items</p>{fields.map((f, idx) => <div key={f.id} className="grid grid-cols-12 gap-2"><Input className="col-span-6" placeholder="Description" {...form.register(`items.${idx}.description`)} /><Input className="col-span-2" type="number" min={1} placeholder="Qty" {...form.register(`items.${idx}.quantity`)} /><Input className="col-span-3" type="number" min={0} step="0.01" placeholder="Unit price" {...form.register(`items.${idx}.unitPrice`)} /><Button type="button" variant="ghost" size="icon" className="col-span-1" onClick={() => remove(idx)} disabled={fields.length === 1} aria-label="Remove item"><Trash2 /></Button></div>)}<Button type="button" variant="outline" size="sm" onClick={() => append({ description: '', quantity: 1, unitPrice: 0 })}><Plus />Add item</Button></div>
      <div className="rounded-md bg-muted/50 p-3 text-sm"><div className="flex justify-between"><span>Subtotal</span><span>{formatMoney(subtotal, form.watch('currency'))}</span></div><div className="flex justify-between"><span>Tax ({tax}%)</span><span>{formatMoney(subtotal * tax / 100, form.watch('currency'))}</span></div><div className="flex justify-between font-semibold"><span>Total</span><span>{formatMoney(subtotal * (1 + tax / 100), form.watch('currency'))}</span></div></div><FormField label="Notes"><Textarea {...form.register('notes')} /></FormField><DialogFooter><Button type="button" variant="outline" onClick={() => setOpen(false)}>Cancel</Button><Button type="submit" loading={create.isPending}>Create draft</Button></DialogFooter></form></DialogContent></Dialog>
