const msSchema = z.object({ name: z.string().min(2), description: z.string().optional(), dueDate: z.string().min(1) });
const settingsSchema = z.object({ name: z.string().min(2), description: z.string().optional(), status: z.enum(['PLANNED', 'ACTIVE', 'ON_HOLD', 'COMPLETED', 'ARCHIVED']), budget: z.coerce.number().min(0).optional(), dueDate: z.string().optional(), startDate: z.string().optional() });
export default function ProjectDetail({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params); const { org, isManagement, isClient, user } = useAuth(); const qc = useQueryClient();
  const [taskOpen, setTaskOpen] = useState(false); const [activeTask, setActiveTask] = useState<Task | null>(null); const [msOpen, setMsOpen] = useState(false); const [memberOpen, setMemberOpen] = useState(false); const [settingsOpen, setSettingsOpen] = useState(false);
  const q = useQuery({ queryKey: ['project', id, org?.id], queryFn: () => api<Project>(`/projects/${id}`), enabled: !!org });
  const activity = useQuery({ queryKey: ['project-activity', id], queryFn: () => api<AuditEvent[]>(`/projects/${id}/activity`), enabled: !!org && !isClient });
  const members = useQuery({ queryKey: ['members', org?.id], queryFn: () => api<Membership[]>('/memberships'), enabled: !!org && isManagement });
  const msForm = useForm<z.infer<typeof msSchema>>({ resolver: zodResolver(msSchema) });
  const settingsForm = useForm<z.infer<typeof settingsSchema>>({ resolver: zodResolver(settingsSchema), values: q.data ? { name: q.data.name, description: q.data.description ?? '', status: q.data.status, budget: q.data.budget ? Number(q.data.budget) : undefined, dueDate: q.data.dueDate?.slice(0, 10) ?? '', startDate: q.data.startDate?.slice(0, 10) ?? '' } : undefined });
  const invalidate = [['project', id], ['projects'], ['dashboard'], ['tasks'], ['milestones']];
  const move = useToastMutation({ mutationFn: (v: { taskId: string; status: Task['status']; position: number }) => api(`/tasks/${v.taskId}/move`, { method: 'PATCH', body: JSON.stringify({ status: v.status, position: v.position }) }), invalidate, onError: () => qc.invalidateQueries({ queryKey: ['project', id] }), onSuccess: (_, v) => { if (v.status === 'DONE') toast.success('Task completed'); } });
  const createMs = useToastMutation({ mutationFn: (d: z.infer<typeof msSchema>) => api('/milestones', { method: 'POST', body: JSON.stringify({ ...d, projectId: id }) }), success: 'Milestone created', invalidate, onSuccess: () => { setMsOpen(false); msForm.reset(); } });
  const toggleMs = useToastMutation({ mutationFn: (m: Milestone) => api(`/milestones/${m.id}`, { method: 'PATCH', body: JSON.stringify({ completed: !m.completedAt }) }), success: 'Milestone updated', invalidate });
  const deleteMs = useToastMutation({ mutationFn: (mid: string) => api(`/milestones/${mid}`, { method: 'DELETE' }), success: 'Milestone deleted', invalidate });
  const addMember = useToastMutation({ mutationFn: (userId: string) => api(`/projects/${id}/members`, { method: 'POST', body: JSON.stringify({ userId }) }), success: 'Member added', invalidate, onSuccess: () => setMemberOpen(false) });
  const removeMember = useToastMutation({ mutationFn: (userId: string) => api(`/projects/${id}/members/${userId}`, { method: 'DELETE' }), success: 'Member removed', invalidate });
  const saveSettings = useToastMutation({ mutationFn: (d: z.infer<typeof settingsSchema>) => api(`/projects/${id}`, { method: 'PATCH', body: JSON.stringify({ ...d, clientId: q.data!.clientId, budget: d.budget || undefined, dueDate: d.dueDate || undefined, startDate: d.startDate || undefined }) }), success: 'Project updated', invalidate, onSuccess: () => setSettingsOpen(false) });
  const upload = useToastMutation({ mutationFn: (file: File) => { const fd = new FormData(); fd.append('file', file); fd.append('projectId', id); return api('/documents/upload', { method: 'POST', body: fd }); }, success: 'Document uploaded', invalidate });
  const download = async (docId: string, name: string) => { try { const res = await fetch(`/api/v1/documents/${docId}/download`, { credentials: 'include', headers: { 'x-organization-id': org!.id } }); if (!res.ok) throw new Error('Download failed'); const blob = await res.blob(); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = name; a.click(); URL.revokeObjectURL(url); } catch (e) { toast.error(e instanceof Error ? e.message : 'Download failed'); } };
  if (q.isLoading) return <div className="space-y-4"><Skeleton className="h-10 w-80" /><Skeleton className="h-96" /></div>;
  if (q.isError) return <ErrorState error={q.error} onRetry={() => q.refetch()} />;
  const p = q.data!; const tasks = p.tasks ?? []; const now = new Date(); const overdue = tasks.filter((t) => t.status !== 'DONE' && t.dueDate && new Date(t.dueDate) < now);
  const openTask = (t: Task | null) => { setActiveTask(t); setTaskOpen(true); };
  const availableMembers = members.data?.filter((m) => m.role !== 'CLIENT' && !p.members.some((pm) => pm.user.id === m.user.id)) ?? [];
  return <div>
    <PageHeader title={p.name} description={`${p.client.name} · ${p.description || 'No description'}`} actions={<><StatusBadge status={p.status} />{!isClient && <Button variant="outline" onClick={() => openTask(null)}><Plus />Add task</Button>}{isManagement && <Button variant="outline" size="icon" onClick={() => setSettingsOpen(true)} aria-label="Project settings"><Settings2 /></Button>}</>} />
    <div className="mb-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
      <Card><CardContent className="p-4"><p className="text-xs text-muted-foreground">Progress</p><div className="mt-2 flex items-center gap-3"><Progress value={p.progress ?? 0} className="flex-1" /><span className="font-semibold">{p.progress ?? 0}%</span></div><p className="mt-1 text-xs text-muted-foreground">{tasks.filter((t) => t.status === 'DONE').length} of {tasks.length} tasks done</p></CardContent></Card>
      <Card><CardContent className="p-4"><p className="text-xs text-muted-foreground">Due date</p><p className="mt-2 flex items-center gap-2 font-semibold"><Calendar className="h-4 w-4 text-muted-foreground" />{formatDate(p.dueDate)}</p></CardContent></Card>
      <Card><CardContent className="p-4"><p className="text-xs text-muted-foreground">Overdue</p><p className={`mt-2 flex items-center gap-2 font-semibold ${overdue.length ? 'text-destructive' : ''}`}><AlertTriangle className="h-4 w-4" />{overdue.length} task{overdue.length === 1 ? '' : 's'}</p></CardContent></Card>
      {!isClient ? <Card><CardContent className="p-4"><p className="text-xs text-muted-foreground">Budget</p><p className="mt-2 font-semibold">{formatMoney(p.budget, p.currency)}</p></CardContent></Card> : <Card><CardContent className="p-4"><p className="text-xs text-muted-foreground">Milestones</p><p className="mt-2 font-semibold">{p.milestones?.filter((m) => m.completedAt).length ?? 0} / {p.milestones?.length ?? 0} complete</p></CardContent></Card>}
    </div>
    <Tabs defaultValue="board"><TabsList className="flex-wrap"><TabsTrigger value="board">Kanban board</TabsTrigger><TabsTrigger value="list">Task list</TabsTrigger><TabsTrigger value="milestones">Milestones</TabsTrigger><TabsTrigger value="timeline">Timeline</TabsTrigger><TabsTrigger value="team">Team</TabsTrigger><TabsTrigger value="files">Files</TabsTrigger>{!isClient && <TabsTrigger value="activity">Activity</TabsTrigger>}</TabsList>
      <TabsContent value="board"><KanbanBoard tasks={tasks} disabled={isClient} onOpen={openTask} onMove={(taskId, status, position) => move.mutate({ taskId, status, position })} />{isClient && <p className="text-xs text-muted-foreground">Read-only board. Use support tickets to request changes.</p>}</TabsContent>
      <TabsContent value="list"><Card><Table><TableHeader><TableRow><TableHead>Task</TableHead><TableHead>Status</TableHead><TableHead>Priority</TableHead><TableHead>Assignee</TableHead><TableHead>Milestone</TableHead><TableHead>Due</TableHead></TableRow></TableHeader><TableBody>{tasks.map((t) => <TableRow key={t.id} className="cursor-pointer" onClick={() => openTask(t)}><TableCell className="font-medium">{t.title}</TableCell><TableCell><StatusBadge status={t.status} /></TableCell><TableCell><StatusBadge status={t.priority} /></TableCell><TableCell>{t.assignee?.name ?? '—'}</TableCell><TableCell className="text-sm text-muted-foreground">{t.milestone?.name ?? '—'}</TableCell><TableCell className={t.dueDate && t.status !== 'DONE' && new Date(t.dueDate) < now ? 'text-destructive' : ''}>{formatDate(t.dueDate)}</TableCell></TableRow>)}</TableBody></Table>{tasks.length === 0 && <p className="p-6 text-center text-sm text-muted-foreground">No tasks yet.</p>}</Card></TabsContent>
      <TabsContent value="milestones"><div className="mb-3 flex justify-end">{isManagement && <Button onClick={() => setMsOpen(true)}><Plus />New milestone</Button>}</div><div className="space-y-3">{p.milestones?.length ? p.milestones.map((m) => { const mt = tasks.filter((t) => t.milestoneId === m.id); const done = mt.filter((t) => t.status === 'DONE').length; return <Card key={m.id}><CardContent className="flex flex-col gap-3 p-4 sm:flex-row sm:items-center"><div className="flex-1"><div className="flex items-center gap-2"><Flag className="h-4 w-4 text-primary" /><p className="font-medium">{m.name}</p>{m.completedAt && <StatusBadge status="COMPLETED" />}</div><p className="mt-1 text-xs text-muted-foreground">Due {formatDate(m.dueDate)} · {done}/{mt.length} tasks · {m.description || 'No description'}</p><Progress value={mt.length ? done / mt.length * 100 : 0} className="mt-2 max-w-xs" /></div>{isManagement && <div className="flex gap-2"><Button variant="outline" size="sm" onClick={() => toggleMs.mutate(m)}><CheckCircle2 />{m.completedAt ? 'Reopen' : 'Mark complete'}</Button><Button variant="ghost" size="icon" onClick={() => deleteMs.mutate(m.id)} aria-label="Delete milestone"><Trash2 /></Button></div>}</CardContent></Card>; }) : <p className="text-sm text-muted-foreground">No milestones yet.</p>}</div></TabsContent>
      <TabsContent value="timeline"><Card><CardContent className="pt-5"><div className="relative border-l-2 border-border pl-6 space-y-6">{[...(p.milestones ?? []).map((m) => ({ date: m.dueDate, title: m.name, type: 'Milestone', done: !!m.completedAt })), ...tasks.filter((t) => t.dueDate).map((t) => ({ date: t.dueDate!, title: t.title, type: 'Task', done: t.status === 'DONE' }))].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime()).map((item, i) => <div key={i} className="relative"><span className={`absolute -left-[31px] top-1 h-4 w-4 rounded-full border-2 border-card ${item.done ? 'bg-emerald-500' : new Date(item.date) < now ? 'bg-destructive' : 'bg-primary'}`} /><p className="text-xs text-muted-foreground">{formatDate(item.date)} · {item.type}</p><p className={`font-medium ${item.done ? 'line-through text-muted-foreground' : ''}`}>{item.title}</p></div>)}{!p.milestones?.length && !tasks.some((t) => t.dueDate) && <p className="text-sm text-muted-foreground">Add due dates to see a timeline.</p>}</div></CardContent></Card></TabsContent>
      <TabsContent value="team"><div className="mb-3 flex justify-end">{isManagement && <Button onClick={() => setMemberOpen(true)} disabled={availableMembers.length === 0}><UserPlus />Add member</Button>}</div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{p.members.map((m) => <Card key={m.id}><CardContent className="flex items-center gap-3 p-4"><Avatar name={m.user.name} /><div className="min-w-0 flex-1"><p className="truncate font-medium">{m.user.name}</p><p className="truncate text-xs text-muted-foreground">{m.user.email} · {tasks.filter((t) => t.assignee?.id === m.user.id && t.status !== 'DONE').length} open tasks</p></div>{isManagement && m.user.id !== user?.id && <Button variant="ghost" size="icon" onClick={() => removeMember.mutate(m.user.id)} aria-label="Remove member"><Trash2 /></Button>}</CardContent></Card>)}</div></TabsContent>
      <TabsContent value="files"><div className="mb-3 flex justify-end"><label className="inline-flex cursor-pointer items-center gap-2 rounded-md bg-primary px-4 py-2 text-sm font-medium text-white hover:bg-primary/90"><Upload className="h-4 w-4" />Upload file<input type="file" className="hidden" onChange={(e) => { const f = e.target.files?.[0]; if (f) upload.mutate(f); e.target.value = ''; }} /></label></div><Card><Table><TableHeader><TableRow><TableHead>Name</TableHead><TableHead>Size</TableHead><TableHead>Uploaded by</TableHead><TableHead>Date</TableHead><TableHead /></TableRow></TableHeader><TableBody>{p.documents?.map((d) => <TableRow key={d.id}><TableCell className="flex items-center gap-2 font-medium"><FileText className="h-4 w-4 text-muted-foreground" />{d.name}</TableCell><TableCell>{(d.sizeBytes / 1024).toFixed(1)} KB</TableCell><TableCell>{d.uploadedBy.name}</TableCell><TableCell>{formatDate(d.createdAt)}</TableCell><TableCell><Button variant="ghost" size="sm" onClick={() => download(d.id, d.name)}><Download />Download</Button></TableCell></TableRow>)}</TableBody></Table>{!p.documents?.length && <p className="p-6 text-center text-sm text-muted-foreground">No files uploaded. PDF, images, text, CSV, ZIP, and Office documents up to 10 MB.</p>}</Card></TabsContent>
      {!isClient && <TabsContent value="activity"><Card><CardContent className="pt-5 space-y-3">{activity.data?.length ? activity.data.map((a) => <div key={a.id} className="border-l-2 border-primary/30 pl-3 text-sm"><p className="font-medium">{titleCase(a.action.replace(/[._]/g, ' '))}</p><p className="text-xs text-muted-foreground">{a.actor?.name ?? 'System'} · {new Date(a.createdAt).toLocaleString()}</p></div>) : <p className="text-sm text-muted-foreground">No activity recorded.</p>}</CardContent></Card></TabsContent>}
    </Tabs>
    <TaskDialog project={p} task={activeTask} open={taskOpen} onOpenChange={setTaskOpen} />
    <Dialog open={msOpen} onOpenChange={setMsOpen}><DialogContent><DialogHeader><DialogTitle>New milestone</DialogTitle></DialogHeader><form onSubmit={msForm.handleSubmit((d) => createMs.mutate(d))} className="space-y-4"><FormField label="Name" required><Input {...msForm.register('name')} /></FormField><FormField label="Description"><Textarea {...msForm.register('description')} /></FormField><FormField label="Due date" required><Input type="date" {...msForm.register('dueDate')} /></FormField><DialogFooter><Button type="submit" loading={createMs.isPending}>Create milestone</Button></DialogFooter></form></DialogContent></Dialog>
    <Dialog open={memberOpen} onOpenChange={setMemberOpen}><DialogContent><DialogHeader><DialogTitle>Add team member</DialogTitle></DialogHeader><div className="space-y-2">{availableMembers.map((m) => <button key={m.id} onClick={() => addMember.mutate(m.user.id)} className="flex w-full items-center gap-3 rounded-md border p-3 text-left hover:bg-muted/40"><Avatar name={m.user.name} /><div><p className="font-medium text-sm">{m.user.name}</p><p className="text-xs text-muted-foreground">{m.user.email} · {m.role}</p></div></button>)}</div></DialogContent></Dialog>
    <Dialog open={settingsOpen} onOpenChange={setSettingsOpen}><DialogContent><DialogHeader><DialogTitle>Project settings</DialogTitle></DialogHeader><form onSubmit={settingsForm.handleSubmit((d) => saveSettings.mutate(d))} className="space-y-4"><FormField label="Name" required><Input {...settingsForm.register('name')} /></FormField><FormField label="Description"><Textarea {...settingsForm.register('description')} /></FormField><div className="grid grid-cols-2 gap-4"><FormField label="Status"><Select value={settingsForm.watch('status')} onValueChange={(v) => settingsForm.setValue('status', v as z.infer<typeof settingsSchema>['status'])}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{['PLANNED', 'ACTIVE', 'ON_HOLD', 'COMPLETED', 'ARCHIVED'].map((s) => <SelectItem key={s} value={s}>{titleCase(s)}</SelectItem>)}</SelectContent></Select></FormField><FormField label="Budget"><Input type="number" min={0} {...settingsForm.register('budget')} /></FormField></div><div className="grid grid-cols-2 gap-4"><FormField label="Start date"><Input type="date" {...settingsForm.register('startDate')} /></FormField><FormField label="Due date"><Input type="date" {...settingsForm.register('dueDate')} /></FormField></div><DialogFooter><Button type="submit" loading={saveSettings.isPending}>Save</Button></DialogFooter></form></DialogContent></Dialog>
  </div>;
}

